const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let saved={};try{saved=JSON.parse(localStorage.getItem('thai-sprout-v1')||'{}')}catch{}
let state={lang:saved.lang==='zh'?'zh':'en',id:letters.some(l=>l.id===saved.id)?saved.id:1,chapter:Math.max(0,Math.min(3,Number(saved.chapter)||0)),tab:'learn',stage:'trace',screen:'lesson',explorer:false};
let progress=saved.progress||{},strokesById={},currentStroke=null,pen='#657f54',meta={},demoFrame=0,demoTime=0,demoPlaying=true,slow=true,artPlaying=!matchMedia('(prefers-reduced-motion: reduce)').matches,artTime=0,quiz=null;
const t=(en,zh)=>state.lang==='zh'?zh:en,L=()=>letters[state.id-1],C=()=>chapters[state.chapter];
state.explorer=!C().ids.includes(state.id);
const done=id=>!!(progress[id]?.heard&&progress[id]?.wrote&&progress[id]?.quiz);
const sprout=`<svg viewBox="0 0 80 80" aria-hidden="true"><path d="M40 64V32" stroke="#537343" stroke-width="5" stroke-linecap="round" fill="none"/><path d="M40 43Q13 43 16 17Q42 16 40 43" fill="#a6be71"/><path d="M40 35Q40 10 67 12Q66 36 40 35" fill="#678b52"/><circle cx="28" cy="28" r="2" fill="#4c673b"/><circle cx="56" cy="23" r="2" fill="#4c673b"/><ellipse cx="40" cy="67" rx="20" ry="5" fill="#e0d9b7"/></svg>`;
function persist(){try{localStorage.setItem('thai-sprout-v1',JSON.stringify({lang:state.lang,id:state.id,chapter:state.chapter,progress}))}catch{}}
function mark(key){progress[state.id]={...progress[state.id],[key]:true};persist()}
function stopSound(){TeacherVoice.stop()}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function setHint(message){if($('#hint-text'))$('#hint-text').textContent=message}
function defaultHint(){if(state.tab==='learn')return t('Tap the sound. Listen, then say it!','點聲音，聽一次，再跟著說！');if(state.tab==='write')return state.stage==='trace'?t('Watch the line. Then trace the pale letter.','先看線條怎麼走，再描淡色字母。'):state.stage==='copy'?t('Look at the little letter. Can you copy it?','看看小字母，你能照著寫嗎？'):t('Your turn! Try the letter on your own.','換你了！試著自己寫一次。');return t('Look at the picture. Tap its letter friend.','看看圖片，點選它的字母朋友。')}
function goLetter(id,explorer=false){stopSound();state.id=id;state.explorer=explorer;state.screen='lesson';state.tab='learn';state.stage='trace';quiz=null;demoFrame=0;demoTime=0;demoPlaying=true;persist();render()}
function playLetter(){const id=state.id;TeacherVoice.play(`letter-${id}`,`assets/letter-${id}.mp3`).then(ok=>{if(ok&&state.id===id){mark('heard');setHint(t('Now you try! Say it out loud.','換你說說看！大聲說一次。'))}})}
function render(){stopSound();padObserver?.disconnect();document.documentElement.lang=state.lang==='zh'?'zh-Hant':'en';const lesson=state.screen==='lesson',step=['learn','write','play'].indexOf(state.tab);
 $('#app').innerHTML=`<header><button class="home-button" id="home" aria-label="${t('Choose a chapter','選擇章節')}"><span>⌂</span> ${t('Home','首頁')}</button><div class="brand">${sprout}<strong>thai sprout<span>.</span></strong></div><div class="top-actions"><button id="language" aria-label="${t('Switch to Chinese hints','切換英文提示')}">${t('中文','English')}</button><button id="parents">${t('Grown-ups','家長')}</button></div></header><main>${lesson?`<div class="lesson-top"><span>${state.explorer?t('Letter explorer','字母探索'):t(`Chapter ${state.chapter+1} · Letter ${C().ids.indexOf(state.id)+1} of 4`,`第 ${state.chapter+1} 章・第 ${C().ids.indexOf(state.id)+1} 個字母`)}</span><div class="step-dots" aria-label="${t('Step','步驟')} ${step+1} / 3">${[0,1,2].map(i=>`<i class="${i<=step?'filled':''}"></i>`).join('')}</div></div><section class="lesson-card"><div class="step-title"><span class="number">${step+1}</span><h1>${state.tab==='learn'?t('Listen & say','聽一聽，說一說'):state.tab==='write'?t('Let’s write','來寫字吧'):t('Find my friend','找找我的朋友')}</h1><button id="hint" class="hint-button">? ${t('Hint','提示')}</button></div><div class="coach" role="status"><span class="coach-face">${sprout}</span><p id="hint-text">${defaultHint()}</p><button id="hint-voice" aria-label="${t('Hear the hint in English','聽英文提示')}">♫</button></div>${state.tab==='learn'?learnHTML():state.tab==='write'?writeHTML():quizHTML()}<div class="bottom-bar"><button class="quiet" id="back">← ${t('Back','上一步')}</button><div class="voice-state"><small id="voice-status" aria-live="polite"></small><button class="stop" id="stop-voice" hidden>${t('Stop sound','停止聲音')}</button></div><button class="next" id="next">${state.tab==='play'?t('Next letter','下一個字母'):t('Next','下一步')} →</button></div></section>`:state.screen==='home'?homeHTML():state.screen==='library'?libraryHTML():completeHTML()}</main>`;
 bind();if(lesson&&state.tab==='write'){setupPad();loadDemo()}if(lesson&&state.tab==='play')bindQuiz();
}
function learnHTML(){let l=L();return `<div class="learn-area"><button class="picture-card" id="word" aria-label="${t('Hear the Thai word','聽泰語詞彙')}">${artSVG(l.art)}<span class="picture-name" lang="th">${l.word}</span><span class="translation">${l.en}${state.lang==='zh'?' · '+l.zh:''}</span></button><div class="letter-card"><span class="huge-letter" lang="th">${l.char}</span><span class="letter-name" lang="th">${l.char} ${l.word}</span><button class="listen" id="listen">♫ <span>${t('Listen','聽一聽')}</span></button><button class="text-button" id="explain">${t('Tell me in English','聽英文解說')} ▷</button></div></div><p class="tiny-note">${t('Teacher voice uses AI. Tap a picture to hear its word.','老師語音由 AI 產生。點圖片可以聽詞彙。')}</p>`}
function writeHTML(){return `<div class="write-area"><div class="demo-box"><div class="demo-top"><span>${t('Watch me','看我寫')}</span><button id="replay" aria-label="${t('Replay writing','重播書寫')}">↻</button></div><canvas class="demo-canvas" id="demo" width="156" height="186" aria-label="${L().char} writing animation"></canvas><div class="demo-buttons"><button id="demo-toggle" aria-label="${t('Pause or play writing','暫停或播放書寫')}">${demoPlaying?'Ⅱ':'▶'}</button><button id="speed">${slow?t('Slow','慢慢看'):t('Normal','正常')}</button></div><p>${t('Watch first.<br>Then try with your finger.','先看一次，<br>再用小手試試看。')}</p></div><div class="writing"><div class="stages" aria-label="${t('Writing mode','書寫模式')}">${[['trace','Trace','描字'],['copy','Copy','照著寫'],['free','Try myself','自己寫']].map(([key,en,zh])=>`<button data-stage="${key}" class="${state.stage===key?'selected':''}" aria-pressed="${state.stage===key}">${t(en,zh)}</button>`).join('')}</div><div class="pad-wrap"><canvas id="pad" aria-label="${t('Draw your letter here','在這裡寫字')}"></canvas><span class="pad-label">${t('Your finger is your pencil!','手指就是你的小鉛筆！')}</span></div><div class="pad-tools"><button id="undo">↶ ${t('Undo','復原')}</button><button id="clear">${t('Try again','重新寫')}</button><button id="save-drawing">↓ ${t('Save picture','存圖片')}</button></div></div></div>`}
function shuffle(a){for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function makeQuiz(){const pool=shuffle((state.explorer?letters.map(l=>l.id):C().ids).filter(id=>id!==state.id));quiz={id:state.id,choices:shuffle([state.id,...pool.slice(0,2)]),solved:false,tries:0}}
function quizHTML(){if(!quiz||quiz.id!==state.id)makeQuiz();return `<div class="quiz-area"><div class="quiz-picture">${artSVG(L().art)}<span>${t(L().en,L().zh)}</span></div><button class="small-listen" id="quiz-listen">♫ ${t('Listen again','再聽一次')}</button><div class="answers">${quiz.choices.map(id=>`<button data-answer="${id}" class="${quiz.solved&&id===state.id?'correct':''}" aria-label="${letters[id-1].char}">${letters[id-1].char}</button>`).join('')}</div><p class="feedback" id="feedback" role="status">${quiz.solved?t('You found it! ★','找到了！★'):t('Which letter is my friend?','哪個字母是我的朋友？')}</p></div>`}
function homeHTML(){return `<section class="home-card"><div class="home-sprout">${sprout}</div><h1>${t('Hello, little explorer!','你好，小小探險家！')}</h1><p>${t('Choose a little adventure. One letter at a time.','選一個小冒險，一次學一個字母。')}</p><div class="chapters">${chapters.map((c,i)=>`<button data-chapter="${i}" style="--chapter-color:${c.color}"><span class="chapter-count">${t('Chapter','第')} ${i+1}${t('',' 章')}</span><strong>${t(c.name,c.zh)}</strong><span class="chapter-letters">${c.ids.map(id=>letters[id-1].char).join(' ')}</span><small>${c.ids.filter(done).length} / 4 ${t('finished','完成')} <span>→</span></small></button>`).join('')}</div></section>`}
function libraryHTML(){return `<section class="home-card"><h1>${t('All our letter friends','全部字母朋友')}</h1><p>${t('Tap a letter to explore.','點一個字母，開始探索。')}</p><div class="alphabet-grid">${letters.map(l=>`<button data-explore="${l.id}" aria-label="${l.char} ${l.en}">${l.char}<small>${t(l.en,l.zh)}</small></button>`).join('')}</div></section>`}
function completeHTML(){return `<section class="finish-card"><div class="big-star">★</div><h1>${t('Look at you grow!','看看你進步了多少！')}</h1><p>${t('Four new letter friends. Take a little stretch!','認識四個字母朋友，伸個懶腰吧！')}</p><div class="celebration-letters">${C().ids.map(id=>`<span>${letters[id-1].char}</span>`).join('')}</div><button id="continue" class="next">${state.chapter<3?t('Next adventure','下一個冒險'):t('Back to my chapters','回到章節')} →</button></section>`}
function bind(){const on=(id,fn)=>{let el=$('#'+id);if(el)el.onclick=fn};on('home',()=>{state.screen='home';render()});on('language',()=>{state.lang=state.lang==='en'?'zh':'en';persist();render()});on('parents',parents);
 on('listen',playLetter);on('word',()=>TeacherVoice.play(`word-${state.id}`,`assets/letter-${state.id}.mp3`));on('explain',()=>TeacherVoice.play(`explain-${state.id}`));on('stop-voice',stopSound);
 on('hint',()=>{setHint(defaultHint());$('.coach')?.classList.add('hint-glow');if(state.tab==='play'&&quiz?.tries>0)$(`[data-answer="${state.id}"]`)?.classList.add('hint-answer');if(state.tab==='write'){demoFrame=0;demoTime=0;demoPlaying=true;paintDemo()}setTimeout(()=>$('.coach')?.classList.remove('hint-glow'),1800)});on('hint-voice',()=>TeacherVoice.play(`hint-${state.tab==='learn'?'listen':state.tab}`));
 on('back',()=>{if(state.tab==='learn')state.screen='home';else state.tab=state.tab==='play'?'write':'learn';render()});
 on('next',()=>{if(state.tab==='learn')state.tab='write';else if(state.tab==='write'){if(!(strokesById[state.id]||[]).some(s=>s.points.length>4)){setHint(t('Try one little line first. It does not have to be perfect!','先試著寫一筆，不用寫得完美喔！'));$('.pad-wrap')?.classList.add('hint-glow');return}state.tab='play'}else{if(!quiz?.solved){setHint(t('Pick a letter first. The Hint button can help!','先選一個字母，「提示」可以幫你喔！'));return}if(state.explorer){goLetter(state.id%44+1,true);return}let i=C().ids.indexOf(state.id);if(i<3){goLetter(C().ids[i+1]);return}state.screen='complete'}render()});
 on('continue',()=>{if(state.chapter<3){state.chapter++;goLetter(C().ids[0])}else{state.screen='home';render()}});$$('[data-chapter]').forEach(b=>b.onclick=()=>{state.chapter=+b.dataset.chapter;goLetter(C().ids.find(id=>!done(id))||C().ids[0])});$$('[data-explore]').forEach(b=>b.onclick=()=>goLetter(+b.dataset.explore,true));$$('[data-stage]').forEach(b=>b.onclick=()=>{state.stage=b.dataset.stage;render()});
 on('undo',()=>{strokesById[state.id]?.pop();drawPad()});on('clear',()=>{strokesById[state.id]=[];drawPad();setHint(defaultHint())});on('save-drawing',saveDrawing);on('replay',()=>{demoFrame=0;demoTime=0;demoPlaying=true;$('#demo-toggle').textContent='Ⅱ';paintDemo()});on('demo-toggle',()=>{demoPlaying=!demoPlaying;$('#demo-toggle').textContent=demoPlaying?'Ⅱ':'▶'});on('speed',()=>{slow=!slow;$('#speed').textContent=slow?t('Slow','慢慢看'):t('Normal','正常')});
}
function bindQuiz(){$('#quiz-listen').onclick=playLetter;$$('[data-answer]').forEach(b=>b.onclick=()=>{if(quiz.solved)return;if(+b.dataset.answer===state.id){quiz.solved=true;mark('quiz');b.classList.add('correct');$('#feedback').textContent=t('You found it! ★','找到了！★');setHint(t('Lovely work! Tap Next letter when you are ready.','做得好！準備好了，就按「下一個字母」。'))}else{quiz.tries++;b.classList.add('try-again');$('#feedback').textContent=t('Good try. Listen once more!','很棒的嘗試，再聽一次吧！');setHint(t('Need help? Tap Hint and look for the glowing letter.','需要幫忙嗎？點「提示」，找找發亮的字母。'));setTimeout(()=>b.classList.remove('try-again'),650)}})}
async function parents(){const d=$('#help');d.innerHTML=`<div class="dialog-head"><h2>${t('For grown-ups','家長設定')}</h2><button id="close-help" aria-label="Close">×</button></div><h3>${t('A little, every day','每天一小步')}</h3><p>${t('Try one letter for 5–10 minutes. Listen → write → play. Give encouragement, not a score. There are 16 starter letters and 44 letters to explore.','每次花 5–10 分鐘學一個字母：聽 → 寫 → 玩。給孩子鼓勵，不必評分。入門有 16 個字母，探索區有全部 44 個。')}</p><button id="all-letters" class="dialog-button">${t('Explore all 44 letters','探索全部 44 個字母')} →</button><h3>${t('Teacher voice','老師語音')}</h3><p id="api-state">${t('Checking voice connection…','檢查語音連線中…')}</p><p>${t('The natural teacher voice is AI-generated. Only fixed lesson scripts are sent to the speech service. The app does not record your child or request a microphone. Original Thai recordings are available as a backup.','自然老師語音由 AI 產生，只傳送固定教材文字給語音服務。不錄製孩子聲音，也不要求麥克風權限。泰語原聲錄音可作備用。')}</p><h3>${t('Learning notes','教學提醒')}</h3><p>${t('This introduces consonants. Picture words name letters; the letter does not always appear first. ฃ and ฅ are historical letters. Tracing is a shape guide; use the animation for direction. Drawing is practice, not automatic handwriting grading.','這是子音入門，圖像詞用來命名字母，目標字母不一定在詞的開頭。ฃ、ฅ 為歷史字母。描字供認形，書寫方向請看動畫。手寫區提供練習，不會自動評分筆順。')}</p><p>${t('Progress is saved in this browser. Drawings clear when the page reloads; save a picture to keep them.','進度保存在這個瀏覽器，重新整理會清除筆跡，可用「存圖片」保留作品。')}</p><p><a href="https://seasite.niu.edu/Thai/basic/alpha_cons_table.htm" target="_blank" rel="noopener">${t('Writing models & original Thai audio: NIU SEAsite','書寫示範與泰語原聲：NIU SEAsite')}</a></p><button id="reset" class="dialog-button">${t('Reset this browser’s progress…','重設這個瀏覽器的學習進度…')}</button>`;
 $('#close-help').onclick=()=>d.close();$('#all-letters').onclick=()=>{d.close();state.screen='library';render()};$('#reset').onclick=()=>{if(confirm(t('Reset learning progress?','要重設學習進度嗎？'))){progress={};persist();d.close();render()}};d.showModal();const status=await TeacherVoice.status();const el=$('#api-state');if(el)el.textContent=status.configured?t('API key is configured. Tap a lesson sound to check playback.','API 金鑰已設定，點課程語音可測試播放。'):t('Teacher API voice is not activated yet. Add OPENROUTER_API_KEY in this Netlify project and redeploy. Thai backup recordings still work.','API 老師語音尚未啟用。請在這個 Netlify 專案加入 OPENROUTER_API_KEY 並重新部署；泰語備用錄音仍可使用。');
}
function init(){fetch('assets/writing.json').then(r=>r.json()).then(data=>{meta=data;if($('#demo'))loadDemo()}).catch(()=>toast(t('Connect to the internet to load the writing demo.','請連上網路以載入書寫示範。')));document.fonts?.ready.then(()=>drawPad());document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSound()});render();requestAnimationFrame(tick)}
